 */
const KLOCKSLAG_ELLER_PRIS = /\b(?:[01]?\d|2[0-3])[.:][0-5]\d\b|\d\s?(?:kr|kronor|SEK)\b/i

function rensaVad(vad) {
  if (!vad) return ''
  return INTERN_ANTECKNING.test(vad) || KLOCKSLAG_ELLER_PRIS.test(vad) ? '' : vad
}

